 if(!config.enabled)return null;
 const summit=data?.levels.at(-1),summitTemp=summit?mountainCurrentValue(summit,'temperature_2m'):NaN,summitDew=summit?mountainCurrentValue(summit,'dew_point_2m'):NaN,summitWind=summit?mountainCurrentValue(summit,'wind_speed_10m'):NaN,summitGust=summit?mountainCurrentValue(summit,'wind_gusts_10m'):NaN,visibility=summit?mountainCurrentValue(summit,'visibility'):NaN,freezing=summit?mountainCurrentValue(summit,'freezing_level_height'):NaN,wetBulb=summit?mountainCurrentValue(summit,'wet_bulb_temperature_2m'):NaN,snowLine=Number.isFinite(freezing)?Math.max(0,freezing-(Number.isFinite(wetBulb)&&wetBulb<0?150:300)):NaN,base=summit?cloudBase(summit.elevation,summitTemp,summitDew):NaN,descent=localMinutesBefore(days[0]?.sunset,45),winter=data?.season==='winter',daylight=summit?mountainDaylightWindow(days,summit.weather):undefined,daylightValues=(key:string)=>summit&&daylight?((summit.weather.hourly.time??[]) as string[]).map((time,index)=>({epoch:mountainTimeEpoch(summit.weather,time),value:mountainHourlyValue(summit,key,index)})).filter(row=>row.epoch>=daylight.sunrise&&row.epoch<=daylight.sunset&&Number.isFinite(row.value)).map(row=>row.value):[],maxCape=daylightValues('cape').length?Math.max(0,...daylightValues('cape')):NaN,maxUv=daylightValues('uv_index').length?Math.max(0,...daylightValues('uv_index')):NaN,summitWindPair=validateWindPair(summitWind,summitGust),summitWindDisplay=summitWindPair.wind,summitGustDisplay=summitWindPair.gust,drift=Boolean(winter&&summit&&summit.newSnow24Cm>=2&&summitGustDisplay>=20),whiteout=Boolean(winter&&summit&&(visibility<1200||mountainCurrentValue(summit,'cloud_cover_low')>=85)&&(summit.newSnow24Cm>.5||summitGustDisplay>=18));
